import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { useAuth } from './AuthContext';
import { useChat } from '@ai-sdk/react';
import { DefaultChatTransport } from 'ai';
import { useUsage } from '@/hooks/useUsage';
import { supabase } from '@/lib/supabase';
import { trackEvent } from '@/lib/analytics';

export type AssistantRole = 'user' | 'assistant' | 'system';

export interface AssistantMessage {
    id: string;
    role: AssistantRole;
    content: string;
    timestamp: string;
    tier?: 1 | 2 | 3;
    tokens_used?: number;
    launchChip?: {
        label: string;
        type: string;
        payload: any;
    };
    suggestions?: string[];
}

interface AssistantContextType {
    isOpen: boolean;
    isMinimized: boolean;
    messages: AssistantMessage[];
    hasUnreadSuggestion: boolean;
    isLoading: boolean;
    error: Error | undefined;
    tierWarning: number | null;
    proactiveSuggestion: {
        text: string;
        action: { label: string; href: string };
    } | null;
    setIsOpen: (open: boolean) => void;
    setIsMinimized: (minimized: boolean) => void;
    sendMessage: (content: string) => void;
    clearMessages: () => void;
    dismissSuggestion: () => void;
    setTierWarning: (tier: number | null) => void;
}

const AssistantContext = createContext<AssistantContextType | undefined>(undefined);

export const AssistantProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { user, token } = useAuth();
    const router = useRouter();
    
    const [isOpen, setOpen] = useState(false);
    const [isMinimized, setMinimized] = useState(false);
    const [hasUnreadSuggestion, setHasUnreadSuggestion] = useState(false);
    const [proactiveSuggestion, setProactiveSuggestion] = useState<{ text: string; action: { label: string; href: string } } | null>(null);
    const [tierWarning, setTierWarning] = useState<number | null>(null);
    const isDemo = router.query.demo === 'true';
    const { refresh: refreshUsage } = useUsage('ai_message_tier1');

    const chat = (useChat as any)({
        api: '/api/home-chat',
        headers: {
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
            ...(isDemo ? { 'x-serify-demo': 'true' } : {})
        },
        onError: (err: any) => {
            if (err.message?.includes('limit_reached') || err.message?.includes('403')) {
                trackEvent('assistant_limit_reached');
            }
        },
        onFinish: () => {
            refreshUsage();
        }
    });

    const { messages: chatMessages, append, reload, input, setInput, isLoading, setMessages, error } = chat;

    const messages = (chatMessages as any[] || []).map(m => ({
        id: m.id,
        role: m.role,
        content: m.content,
        timestamp: m.createdAt ? new Date(m.createdAt).toISOString() : new Date().toISOString(),
        suggestions: m.suggestions 
    })) as AssistantMessage[];

    
    useEffect(() => {
        if (!user || user.subscriptionTier !== 'pro_plus' || messages.length === 0) return;

        const saveMessages = async () => {
            await supabase.from('assistant_conversations').upsert({
                user_id: user.id,
                messages: messages,
                last_message_at: new Date().toISOString()
            }, { onConflict: 'user_id' });
        };

        const timeout = setTimeout(saveMessages, 2000);
        return () => clearTimeout(timeout);
    }, [messages, user]);

    
    useEffect(() => {
        if (!user || user.subscriptionTier !== 'pro_plus' || messages.length > 0) return;

        const loadMessages = async () => {
            const { data } = await supabase.from('assistant_conversations')
                .select('messages')
                .eq('user_id', user.id)
                .maybeSingle();

            if (data?.messages && messages.length === 0) {
                setMessages(data.messages);
            }
        };

        loadMessages();
    }, [user, setMessages, messages.length]);

    const sendMessage = useCallback(async (content: string) => {
        if (!content.trim()) return;

        try {
            if (append) {
                await append({
                    role: 'user',
                    content: content
                });
            } else {
                console.error('No append function found for assistant chat');
            }
        } catch (err) {
            console.error('Error sending message:', err);
        }
    }, [append, chat]);

    const clearMessages = useCallback(() => {
        
        
    }, []);

    const dismissSuggestion = useCallback(() => {
        setHasUnreadSuggestion(false);
        setProactiveSuggestion(null);
    }, []);

    
    useEffect(() => {
        if (!user) return;

        const checkSuggestions = async () => {
            
            const { data: dueData } = await supabase.from('knowledge_nodes')
                .select('id')
                .eq('user_id', user.id)
                .in('current_mastery', ['shaky', 'revisit'])
                .limit(5);

            if (dueData && dueData.length > 0) {
                setHasUnreadSuggestion(true);
                setProactiveSuggestion({
                    text: `You have ${dueData.length} concepts due for review today (~${dueData.length * 2} min).`,
                    action: { label: 'Start Review', href: '/practice' }
                });
                return;
            }

            
            const { data: sessionData } = await supabase.from('reflection_sessions')
                .select('id, title, created_at, depth_score')
                .eq('user_id', user.id)
                .lt('depth_score', 70)
                .gte('created_at', new Date(Date.now() - 48 * 60 * 60 * 1000).toISOString())
                .order('created_at', { ascending: false })
                .limit(1);

            if (sessionData && sessionData.length > 0) {
                setHasUnreadSuggestion(true);
                setProactiveSuggestion({
                    text: `Your last session "${sessionData[0].title}" has unresolved gaps.`,
                    action: { label: 'Fix them now', href: `/session/${sessionData[0].id}` }
                });
            }
        };

        checkSuggestions();
    }, [user]);

    
    useEffect(() => {
        if (isOpen) {
            setHasUnreadSuggestion(false);
        }
    }, [isOpen]);

    return (
        <AssistantContext.Provider
            value={{
                isOpen,
                isMinimized,
                messages,
                hasUnreadSuggestion,
                isLoading,
                error: (error as Error),
                tierWarning,
                proactiveSuggestion,
                setIsOpen: setOpen,
                setIsMinimized: setMinimized,
                sendMessage,
                clearMessages,
                dismissSuggestion,
                setTierWarning,
            }}
        >
            {children}
        </AssistantContext.Provider>
    );
};

export const useAssistant = () => {
    const context = useContext(AssistantContext);
    if (context === undefined) {
        throw new Error('useAssistant must be used within an AssistantProvider');
    }
    return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';
import { User, Session } from '@supabase/supabase-js';

export interface UserProfile {
    id: string;
    email: string;
    displayName: string;
    createdAt: string;
    subscriptionTier: string;
    plan?: string;
    preferences: { tone?: string; questionCount?: number } | null;
    onboardingCompleted: boolean;
    userType?: string;
    tokensUsed: number;
    monthlyLimit: number;
    percentUsed: number;
}

interface AuthContextType {
    user: UserProfile | null;
    token: string | null;
    loading: boolean;
    login: (email: string, password: string) => Promise<UserProfile>;
    register: (email: string, password: string, displayName: string) => Promise<void>;
    loginWithGoogle: () => Promise<void>;
    logout: () => Promise<void>;
    updatePreferences: (prefs: Partial<UserProfile['preferences']>) => Promise<void>;
    markOnboardingComplete: () => Promise<void>;
    refreshUsage: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
    const [user, setUser] = useState<UserProfile | null>(null);
    const [token, setToken] = useState<string | null>(null);
    const [loading, setLoading] = useState(true);

    const fetchProfileAndUsage = async (authUser: User, sessionToken?: string): Promise<UserProfile | null> => {
        try {
            
            const profilePromise = supabase
                .from('profiles')
                .select('*')
                .eq('id', authUser.id)
                .single();

            const profileTimeout = new Promise<{ data?: any; error?: any; timeout: boolean }>((resolve) => 
                setTimeout(() => resolve({ timeout: true }), 5000)
            );
            
            const profileRaceResult = await Promise.race([
                profilePromise.then(res => ({ data: res.data, error: res.error, timeout: false })),
                profileTimeout
            ]);

            const isTimeout = profileRaceResult.timeout || false;
            const hasError = profileRaceResult.error || !profileRaceResult.data;

            let profile = null;
            
            if (isTimeout) {
                console.warn('[AuthContext] Profile fetch timeout (5s), using fallback');
            } else if (hasError) {
                console.error('[AuthContext] Error fetching profile, using fallback:', profileRaceResult.error);
            } else {
                profile = profileRaceResult.data;
            }

            let tokensUsed = 0;
            let monthlyLimit = 100;
            let percentUsed = 0;
            let plan = profile?.subscription_tier || 'free';

            try {
                const jwt = sessionToken || (await supabase.auth.getSession()).data.session?.access_token;
                
                if (jwt) {
                    const usageResPromise = fetch('/api/usage', {
                        headers: {
                            Authorization: `Bearer ${jwt}`
                        }
                    });
                    const usageTimeout = new Promise<null>((resolve) => setTimeout(() => resolve(null), 8000));
                    const usageRes = await Promise.race([
                        usageResPromise as any,
                        usageTimeout as any
                    ]);

                    if (usageRes && usageRes.ok) {
                        const usageData = await usageRes.json();
                        tokensUsed = usageData.tokensUsed || 0;
                        monthlyLimit = usageData.monthlyLimit || 100;
                        percentUsed = usageData.percentUsed || 0;
                        plan = usageData.plan || plan;
                    }
                }
            } catch (usageError) {
                console.warn('Could not fetch usage info:', usageError);
            }

            const parsedPreferences = profile?.preferences 
                ? (typeof profile.preferences === 'string' ? JSON.parse(profile.preferences) : profile.preferences)
                : { tone: 'encouraging', questionCount: 5 };

            return {
                id: authUser.id,
                email: authUser.email || '',
                displayName: profile?.display_name || authUser.user_metadata?.display_name || 'User',
                createdAt: profile?.created_at || authUser.created_at || new Date().toISOString(),
                subscriptionTier: profile?.subscription_tier || 'free',
                plan: plan,
                preferences: parsedPreferences,
                onboardingCompleted: profile?.onboarding_completed ?? true, 
                userType: profile?.user_type || 'user',
                tokensUsed,
                monthlyLimit,
                percentUsed,
            };
        } catch (error) {
            console.error('Error in fetchProfileAndUsage, returning fallback profile:', error);
            
            return {
                id: authUser.id,
                email: authUser.email || '',
                displayName: authUser.user_metadata?.display_name || 'User',
                createdAt: authUser.created_at || new Date().toISOString(),
                subscriptionTier: 'free',
                plan: 'free',
                preferences: { tone: 'encouraging', questionCount: 5 },
                onboardingCompleted: true,
                userType: 'user',
                tokensUsed: 0,
                monthlyLimit: 10,
                percentUsed: 0,
            };
        }
    };

    const handleAuthChange = async (event: string, session: Session | null) => {
        try {
            console.log(`[AuthContext] handleAuthChange event: ${event}`);
            if (session?.user) {
                setToken(session.access_token);
                
                const userProfile = await fetchProfileAndUsage(session.user, session.access_token);
                
                if (userProfile) {
                    setUser(userProfile);
                } else {
                    
                    setUser(prev => prev);
                }
            } else {
                setUser(null);
                setToken(null);
            }
        } finally {
            
            setLoading(false);
        }
    };

    useEffect(() => {
        let mounted = true;
        
        // Logging to track initialization flow
        console.log('[AuthContext] Provider mounted, initializing auth flow...');

        // Safety timeout to prevent infinite loading if Supabase hangs
        const safetyTimeout = setTimeout(() => {
            if (mounted && loading) {
                console.warn('[AuthContext] Safety timeout triggered after 4s (Aggressive). Forcing loading false.');
                setLoading(false);
            }
        }, 4000);

        async function loadInitialSession() {
            try {
                console.log('[AuthContext] loadInitialSession starting...');
                const sessionRes = await supabase.auth.getSession();
                const session = sessionRes.data.session;
                const error = sessionRes.error;

                console.log('[AuthContext] getSession result:', session ? 'Session found' : 'No session', error || '');
                if (error) throw error;
                if (mounted) {
                    await handleAuthChange('INITIAL_SESSION', session);
                }
            } catch (err) {
                console.error('[AuthContext] loadInitialSession error:', err);
                if (mounted) setLoading(false);
            } finally {
                if (mounted) {
                    console.log('[AuthContext] loadInitialSession completed.');
                }
                clearTimeout(safetyTimeout);
            }
        }
        
        loadInitialSession();

        const { data: { subscription } } = supabase.auth.onAuthStateChange(handleAuthChange);

        return () => {
            mounted = false;
            subscription.unsubscribe();
            clearTimeout(safetyTimeout);
        };
    }, []);

    const login = async (email: string, password: string): Promise<UserProfile> => {
        const { data, error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;
        if (!data.user) throw new Error('No user returned from login');
        
        const profile = await fetchProfileAndUsage(data.user, data.session?.access_token);
        if (!profile) throw new Error('Failed to load user profile');
        
        setUser(profile);
        setToken(data.session?.access_token || null);
        return profile;
    };

    const register = async (email: string, password: string, displayName: string): Promise<void> => {
        const { error } = await supabase.auth.signUp({
            email,
            password,
            options: {
                data: {
                    display_name: displayName,
                }
            }
        });
        if (error) throw error;
    };

    const loginWithGoogle = async (): Promise<void> => {
        const { error } = await supabase.auth.signInWithOAuth({
            provider: 'google',
            options: {
                redirectTo: `${window.location.origin}/api/auth/callback`
            }
        });
        if (error) throw error;
    };

    const logout = async (): Promise<void> => {
        const { error } = await supabase.auth.signOut();
        if (error) throw error;
        setUser(null);
        setToken(null);
    };

    const updatePreferences = async (prefs: Partial<UserProfile['preferences']>): Promise<void> => {
        if (!user) return;
        
        const newPrefs = { ...user.preferences, ...prefs };
        const { error } = await supabase
            .from('profiles')
            .update({ preferences: newPrefs as any })
            .eq('id', user.id);
            
        if (error) throw error;
        setUser({ ...user, preferences: newPrefs });
    };

    const markOnboardingComplete = async (): Promise<void> => {
        if (!user) return;
        
        const { error } = await supabase
            .from('profiles')
            .update({ 
                onboarding_completed: true,
                onboarding_completed_at: new Date().toISOString()
            })
            .eq('id', user.id);
            
        if (error) throw error;
        setUser({ ...user, onboardingCompleted: true });
    };

    const refreshUsage = async (): Promise<void> => {
        if (!user) return;
        const authSession = await supabase.auth.getSession();
        if (authSession.data.session?.user) {
            const updatedProfile = await fetchProfileAndUsage(authSession.data.session.user, authSession.data.session.access_token);
            if (updatedProfile) {
                setUser(updatedProfile);
            }
        }
    };

    return (
        <AuthContext.Provider
            value={{
                user,
                token,
                loading,
                login,
                register,
                loginWithGoogle,
                logout,
                updatePreferences,
                markOnboardingComplete,
                refreshUsage
            }}
        >
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
}

import React, { createContext, useContext, useEffect, useState } from 'react';
import { useAuth } from './AuthContext';
import { getAllEnabledFlags } from '@/lib/flags';

type FeatureFlagContextType = {
    flags: string[];
    isEnabled: (flagKey: string) => boolean;
    isLoading: boolean;
};

const FeatureFlagContext = createContext<FeatureFlagContextType | undefined>(undefined);

export const FeatureFlagProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { user } = useAuth();
    const [flags, setFlags] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        async function loadFlags() {
            try {
                
                const metadata = user ? { tier: user.subscriptionTier } : undefined;
                const enabledFlags = await getAllEnabledFlags(user?.id, metadata);
                setFlags(enabledFlags);
            } catch (error) {
                console.error('[Feature Flags] Failed to load flags:', error);
            } finally {
                setIsLoading(false);
            }
        }

        loadFlags();
    }, [user?.id, user?.subscriptionTier]);

    const isEnabled = (flagKey: string) => flags.includes(flagKey);

    return (
        <FeatureFlagContext.Provider value={{ flags, isEnabled, isLoading }}>
            {children}
        </FeatureFlagContext.Provider>
    );
};

export const useFeatureFlags = () => {
    const context = useContext(FeatureFlagContext);
    if (context === undefined) {
        throw new Error('useFeatureFlags must be used within a FeatureFlagProvider');
    }
    return context;
};

export const FeatureFlag: React.FC<{ 
    flag: string; 
    children: React.ReactNode;
    fallback?: React.ReactNode;
}> = ({ flag, children, fallback = null }) => {
    const { isEnabled, isLoading } = useFeatureFlags();

    if (isLoading) return null; 

    return isEnabled(flag) ? <>{children}</> : <>{fallback}</>;
};

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';

export interface SessionMaterialsSummary {
    flashcards: {
        exists: boolean;
        cardCount?: number;
        generatedAt?: string;
        progress?: any;
        generationCount?: number;
    };
    practiceQuiz: {
        exists: boolean;
        questionCount?: number;
        generatedAt?: string;
        attempts?: any;
        generationCount?: number;
    };
    deepDive: {
        exists: boolean;
        conceptName?: string;
        generatedAt?: string;
        readAt?: string;
        generationCount?: number;
    };
    conceptExplanations: { exists: boolean; count: number; conceptIds: string[] };
    tutorConversation: { exists: boolean; messageCount?: number; lastMessageAt?: string };
    feynman: { exists: boolean; attemptCount: number; latestAssessment?: any };
}

const emptyMaterials: SessionMaterialsSummary = {
    flashcards: { exists: false },
    practiceQuiz: { exists: false },
    deepDive: { exists: false },
    conceptExplanations: { exists: false, count: 0, conceptIds: [] },
    tutorConversation: { exists: false },
    feynman: { exists: false, attemptCount: 0 }
};

export function useSessionMaterials(sessionId: string | null) {
    const [materials, setMaterials] = useState<SessionMaterialsSummary>(emptyMaterials);
    const { token } = useAuth();
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<Error | null>(null);

    const fetchMaterials = useCallback(async () => {
        if (!sessionId || sessionId === 'undefined') {
            return;
        }

        setIsLoading(true);
        setError(null);

        try {
            if (!token) return;

            const response = await fetch(`/api/sessions/${sessionId}/materials`, {
                headers: {
                    Authorization: `Bearer ${token}`
                }
            });

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}));
                const errorMsg = errorData.error || response.statusText;
                setError(new Error(`Failed to fetch materials: ${errorMsg}`));
                return;
            }

            const data = await response.json();
            setMaterials(data);
        } catch (err: any) {
            setError(err);
            console.error('Error fetching materials summary:', err);
        } finally {
            setIsLoading(false);
        }
    }, [sessionId]);

    useEffect(() => {
        fetchMaterials();
    }, [fetchMaterials]);

    return { materials, isLoading, error, refetch: fetchMaterials };
}
